/**
 * FreeWire Phase 7 — Repair Engine
 *
 * 위반(Violation)을 받아서 최소한의 그래프 패치를 생성한다.
 * 전체를 재생성하지 않고, 필요한 부분만 수술한다.
 *
 * 패치 타입:
 *   add_wire    — 두 노드를 연결하는 와이어 추가
 *   add_node    — 누락된 노드 추가 (+ 자동 위치 계산)
 *   fix_prop    — 노드의 props 수정
 *   remove_node — 의미 없는 노드 제거 (고아 노드)
 */

'use strict';

let _repairIdCtr = 1;
const rid = () => `rp-${_repairIdCtr++}`;

// ─── 패치 구조 ─────────────────────────────────────────────────

class GraphPatch {
  constructor({ type, description, confidence, apply }) {
    this.id          = rid();
    this.type        = type;        // 'add_wire' | 'add_node' | 'fix_prop' | 'remove_node'
    this.description = description; // 사람이 읽을 수 있는 설명
    this.confidence  = confidence;  // 0-1, 이 패치가 맞을 확률
    this._apply      = apply;       // (nodes, wires) => void
  }

  apply(nodes, wires) {
    this._apply(nodes, wires);
    return this;
  }
}

// ─── Repair Engine ─────────────────────────────────────────────

class RepairEngine {
  /**
   * 위반 목록 → 패치 목록 (신뢰도 순 정렬)
   * @param {ContractViolation[]} violations
   * @param {Map} nodes
   * @param {Map} wires
   * @returns {GraphPatch[]}
   */
  suggest(violations, nodes, wires) {
    const nodesArr = [...nodes.values()].map(v => v.def ?? v);
    const wiresArr = [...wires.values()];
    const patches  = [];

    // 구조적 경고도 수리 대상 (state 바인딩 등)
    const FIXABLE_WARNINGS = new Set(['wire_state_to_display', 'connect_orphan']);

    for (const v of violations) {
      if (v.severity !== 'error' && !FIXABLE_WARNINGS.has(v.repairHint)) continue;

      const p = this._violationToPatch(v, nodesArr, wiresArr);
      if (p) patches.push(p);
    }

    // 신뢰도 높은 것 먼저, 중복 제거
    return this._deduplicate(patches).sort((a, b) => b.confidence - a.confidence);
  }

  /**
   * 패치들을 실제 그래프에 적용
   * @param {GraphPatch[]} patches
   * @param {Map} nodes
   * @param {Map} wires
   * @param {Function} nextId - ID 생성기
   * @returns {{ applied: GraphPatch[], skipped: GraphPatch[] }}
   */
  applyPatches(patches, nodes, wires, nextId) {
    const applied = [], skipped = [];

