/**
 * FreeWire Phase 8 — Neuro-Symbolic Wire
 * intent-wire.js
 *
 * 와이어(Wire)를 "데이터 파이프"에서 "의도(Intent) 전달체"로 승격시킨다.
 *
 * 기존 와이어: A.output(data) ──[portType 매칭]──> B.input(data)
 * IntentWire:  A.output ──[semantic intent + schema]──> B.input
 *               └── 불일치 시 에러 대신 AdapterNode 자동 삽입
 *
 * Intent 구조:
 *   semantic  — 자연어 의도 ("사용자 이메일을 인증 서비스로 전달")
 *   schema    — 구조적 타입 힌트 ({ type: 'string', format: 'email' })
 *   context   — 실행 컨텍스트 ({ domain: 'auth', urgency: 'high' })
 *   facts     — 이 와이어가 참이라고 전제하는 Facts (Phase 7 연동)
 */

'use strict';

let _wireIdCtr = 1;
const wid = () => `iw-${_wireIdCtr++}`;

// ─── WireIntent ────────────────────────────────────────────────
// 와이어가 운반하는 "의도" 객체

class WireIntent {
  /**
   * @param {object} opts
   * @param {string} opts.semantic   자연어 의도 설명
   * @param {object} [opts.schema]   JSON Schema 서브셋 (type, format, properties 등)
   * @param {object} [opts.context]  실행 컨텍스트 (domain, urgency, locale 등)
   * @param {string[]} [opts.facts]  전제 Facts (Phase 7 FACT_LIBRARY 키)
   */
  constructor({ semantic, schema = {}, context = {}, facts = [] }) {
    if (!semantic || typeof semantic !== 'string')
      throw new Error('WireIntent: semantic(자연어 의도)는 필수 문자열입니다');

    this.semantic = semantic;
    this.schema   = schema;    // 구조적 타입 힌트
    this.context  = context;   // 실행 컨텍스트
    this.facts    = facts;     // 전제 사실들
  }

  /**
   * 두 intent가 의미적으로 호환 가능한지 빠른 판단
   * (정밀 판단은 MismatchDetector가 담당)
   * @param {WireIntent} other
   * @returns {'compatible' | 'uncertain' | 'incompatible'}
   */
  compatibilityHint(other) {
    // schema 타입이 명시적으로 다르면 incompatible
    if (this.schema.type && other.schema.type &&
        this.schema.type !== other.schema.type &&
        other.schema.type !== 'any') {
      return 'incompatible';
    }

    // domain 컨텍스트가 완전히 다르면 uncertain (어댑터 필요 가능)
    if (this.context.domain && other.context.domain &&
        this.context.domain !== other.context.domain) {
      return 'uncertain';
    }

    return 'compatible';
  }

  toJSON() {
    return {
      semantic: this.semantic,
      schema:   this.schema,
      context:  this.context,
      facts:    this.facts,
    };
  }
}

// ─── IntentWire ────────────────────────────────────────────────

class IntentWire {
  /**
   * @param {object} opts
   * @param {string} opts.fromNodeId    출발 노드 ID
   * @param {string} opts.fromPortId    출발 포트 이름
   * @param {string} opts.toNodeId      도착 노드 ID
   * @param {string} opts.toPortId      도착 포트 이름
   * @param {WireIntent} opts.intent    이 와이어의 의도
   */
  constructor({ fromNodeId, fromPortId, toNodeId, toPortId, intent }) {
    this.id          = wid();
    this.fromNodeId  = fromNodeId;
    this.fromPortId  = fromPortId;
    this.toNodeId    = toNodeId;
    this.toPortId    = toPortId;
    this.intent      = intent instanceof WireIntent ? intent : new WireIntent(intent);

    // 실행 상태
    this.status      = 'pending';    // 'pending' | 'compatible' | 'mismatched' | 'adapted' | 'active'
    this.adapterNodeId = null;       // 어댑터 삽입 시 채워짐
    this.mismatchReport = null;      // 불일치 상세 보고서
  }

  /**
   * 어댑터 노드가 삽입되었음을 표시
   * @param {string} adapterNodeId
   */
  markAdapted(adapterNodeId) {
    this.status        = 'adapted';
    this.adapterNodeId = adapterNodeId;
  }

  markActive()  { this.status = 'active'; }
  markMismatch(report) {
    this.status = 'mismatched';
    this.mismatchReport = report;
  }

  /** 연결 방향 요약 */
  describe() {
    const adapted = this.adapterNodeId ? ` [어댑터: ${this.adapterNodeId}]` : '';
    return `${this.fromNodeId}.${this.fromPortId} ──[${this.intent.semantic}]──> ${this.toNodeId}.${this.toPortId}${adapted}`;
  }

  toJSON() {
    return {
      id:            this.id,
      fromNodeId:    this.fromNodeId,
      fromPortId:    this.fromPortId,
      toNodeId:      this.toNodeId,
      toPortId:      this.toPortId,
      intent:        this.intent.toJSON(),
      status:        this.status,
      adapterNodeId: this.adapterNodeId,
    };
  }
}

// ─── IntentWireBuilder (편의 생성자) ──────────────────────────

class IntentWireBuilder {
  constructor(fromNodeId, fromPortId) {
    this._from = { fromNodeId, fromPortId };
    this._intent = null;
  }

  carrying(semantic, schema = {}, context = {}, facts = []) {
    this._intent = new WireIntent({ semantic, schema, context, facts });
    return this;
  }

  to(toNodeId, toPortId) {
    if (!this._intent)
      throw new Error('IntentWireBuilder: .carrying()로 의도를 먼저 설정하세요');
    return new IntentWire({
      ...this._from,
      toNodeId,
      toPortId,
      intent: this._intent,
    });
  }
}

/** 빌더 진입점 */
const wire = (fromNodeId, fromPortId) => new IntentWireBuilder(fromNodeId, fromPortId);

module.exports = { WireIntent, IntentWire, IntentWireBuilder, wire };

