/**
 * FreeWire Phase 8 — Neuro-Symbolic Wire
 * mismatch-detector.js
 *
 * 두 노드를 연결할 때 "불일치"를 감지한다.
 *
 * 기존 방식: portType 매트릭스만 체크 → 불일치 시 에러
 * 이 방식:   구조적(Structural) + 의미적(Semantic) 불일치 모두 감지
 *             → 에러 대신 MismatchReport 반환 → AdapterGenerator에게 전달
 *
 * MismatchType:
 *   'none'        — 완전 호환 (어댑터 불필요)
 *   'structural'  — 포트 타입 불일치 (data ↔ component 등)
 *   'semantic'    — 의미적 불일치 (schema 타입, domain 충돌)
 *   'hybrid'      — 구조적 + 의미적 동시 불일치
 */

'use strict';

// ─── PORT_COMPAT (node-spec.js에서 재사용) ────────────────────

const PORT_COMPAT = {
  component: ['component', 'any'],
  data:      ['data', 'any'],
  logic:     ['logic', 'any'],
  event:     ['event', 'any'],
  any:       ['component', 'data', 'logic', 'event', 'any'],
};

function isPortCompatible(outputType, inputType) {
  const allowed = PORT_COMPAT[outputType] || [];
  return allowed.includes(inputType);
}

// ─── 의미적 불일치 규칙 테이블 ─────────────────────────────────
// [출발 schema 패턴, 도착 schema 패턴, 불일치 설명, 어댑터 힌트]

const SEMANTIC_RULES = [
  // 타입 불일치
  {
