        confidence: 1.0, fromSchema, toSchema, fromContext, toContext,
      });
    }

    if (structuralMismatch && semanticMismatch) {
      return new MismatchReport({
        type: 'hybrid',
        description: `${structuralMismatch.description} + ${semanticMismatch.description}`,
        adapterHint: semanticMismatch.adapterHint || 'universal',
        confidence: Math.min(structuralMismatch.confidence, semanticMismatch.confidence),
        fromSchema, toSchema, fromContext, toContext,
      });
    }

    if (structuralMismatch) {
      return new MismatchReport({
        ...structuralMismatch,
        type: 'structural',
        fromSchema, toSchema, fromContext, toContext,
      });
    }

    return new MismatchReport({
      ...semanticMismatch,
      type: 'semantic',
      fromSchema, toSchema, fromContext, toContext,
    });
  }

  // ─── 내부 헬퍼 ──────────────────────────────────────────────

  _findPort(node, direction, portName) {
    const ports = node[direction] || [];
    return ports.find(p => p.name === portName) || null;
  }

  _checkStructural(fromPortDef, toPortDef) {
    if (!fromPortDef || !toPortDef) return null; // 포트 정보 없으면 건너뜀

    const outType = fromPortDef.portType || 'any';
    const inType  = toPortDef.portType  || 'any';

