/**
 * FreeWire Phase 8 — Neuro-Symbolic Wire
 * intent-wire.fl
 *
 * 와이어(Wire)를 "데이터 파이프"에서 "의도(Intent) 전달체"로 승격
 *
 * 기존:  A.output ──[portType]──> B.input  →  불일치 시 에러
 * 신규:  A.output ──[Intent]──>  B.input  →  불일치 시 어댑터 자동 생성
 *
 * Intent = 이 와이어가 "왜" 연결되었는가를 담는 의미 컨테이너
 */

// ─── WireIntent ────────────────────────────────────────────────
// 와이어 위를 흐르는 "의도" — 타입이 아닌 의미

struct WireIntent {
  semantic: string,    // 자연어 의도 ("사용자 이메일을 인증 서비스로 전달")
  schema_type: string, // 구조적 타입 힌트 ("string", "object", "array", "number", "any")
  schema_format: string, // 포맷 힌트 ("email", "url", "date", "json", "csv", "markdown")
  domain: string,      // 실행 도메인 ("ui", "api", "auth", "data", "payment", "nav")
  urgency: string,     // 긴급도 ("high", "normal", "low")
  facts: string        // 전제 사실 목록 (쉼표 구분, Phase 7 연동)
}

// ─── IntentWire ────────────────────────────────────────────────
// 두 노드를 연결하며 "의도"를 운반하는 와이어

struct IntentWire {
  id: string,
  from_node: string,    // 출발 노드 ID
  from_port: string,    // 출발 포트 이름
  to_node: string,      // 도착 노드 ID
  to_port: string,      // 도착 포트 이름
  intent: WireIntent,

  // 실행 상태
  status: string,       // "pending" | "compatible" | "mismatched" | "adapted" | "active"
  adapter_node_id: string, // 어댑터 삽입 시 채워짐 (없으면 "")
  mismatch_type: string    // 불일치 유형 (없으면 "")
}

// ─── 빠른 호환성 힌트 ──────────────────────────────────────────

fn intentCompatibilityHint(from_intent: WireIntent, to_schema_type: string, to_domain: string) -> string {
  // 타입이 명시적으로 다르면 incompatible
  if from_intent.schema_type != "any" && to_schema_type != "any" {
    if from_intent.schema_type != to_schema_type && to_schema_type != "" {
      return "incompatible"
    }
  }

  // 도메인이 다르면 uncertain (어댑터 필요 가능)
  if from_intent.domain != "" && to_domain != "" {
    if from_intent.domain != to_domain {
      return "uncertain"
    }
  }

  return "compatible"
}

// ─── IntentWire 생성 ───────────────────────────────────────────

fn makeWireIntent(semantic: string, schema_type: string, domain: string) -> WireIntent {
  return {
    semantic: semantic,
    schema_type: schema_type,
    schema_format: "",
    domain: domain,
    urgency: "normal",
    facts: ""
  }
}

fn makeWireIntentFull(semantic: string, schema_type: string, schema_format: string, domain: string, urgency: string, facts: string) -> WireIntent {
  return {
    semantic: semantic,
    schema_type: schema_type,
    schema_format: schema_format,
    domain: domain,
    urgency: urgency,
    facts: facts
  }
}

fn makeIntentWire(id: string, from_node: string, from_port: string, to_node: string, to_port: string, intent: WireIntent) -> IntentWire {
  return {
    id: id,
    from_node: from_node,
    from_port: from_port,
    to_node: to_node,
    to_port: to_port,
    intent: intent,
    status: "pending",
    adapter_node_id: "",
    mismatch_type: ""
  }
}

// ─── 와이어 상태 전환 ──────────────────────────────────────────

fn markWireAdapted(w: IntentWire, adapter_id: string) -> IntentWire {
  return {
    id: w.id,
    from_node: w.from_node,
    from_port: w.from_port,
    to_node: w.to_node,
    to_port: w.to_port,
    intent: w.intent,
    status: "adapted",
    adapter_node_id: adapter_id,
    mismatch_type: w.mismatch_type
  }
}

fn markWireMismatch(w: IntentWire, mismatch_type: string) -> IntentWire {
  return {
    id: w.id,
    from_node: w.from_node,
    from_port: w.from_port,
    to_node: w.to_node,
    to_port: w.to_port,
    intent: w.intent,
    status: "mismatched",
    adapter_node_id: "",
    mismatch_type: mismatch_type
  }
}

fn markWireActive(w: IntentWire) -> IntentWire {
  return {
    id: w.id,
    from_node: w.from_node,
    from_port: w.from_port,
    to_node: w.to_node,
    to_port: w.to_port,
    intent: w.intent,
    status: "active",
    adapter_node_id: w.adapter_node_id,
    mismatch_type: w.mismatch_type
  }
}

// ─── 와이어 설명 생성 ──────────────────────────────────────────

fn describeWire(w: IntentWire) -> string {
  let adapted = ""
  if w.adapter_node_id != "" {
    adapted = " [어댑터: " + w.adapter_node_id + "]"
  }
  return w.from_node + "." + w.from_port + " ──[" + w.intent.semantic + "]──> " + w.to_node + "." + w.to_port + adapted
}

// ─── 테스트 엔트리 ────────────────────────────────────────────

fn main() -> int {
  // 기본 IntentWire 생성 테스트
  let intent = makeWireIntent("사용자 이메일을 인증 서비스로 전달", "string", "auth")
  let w = makeIntentWire("iw-001", "input-node", "value", "auth-node", "email", intent)

  print("생성된 와이어: " + describeWire(w))
  print("상태: " + w.status)

  // 호환성 힌트 테스트
  let hint = intentCompatibilityHint(intent, "object", "api")
  print("호환성 힌트 (string→object, auth→api): " + hint)

  let hint2 = intentCompatibilityHint(intent, "string", "auth")
  print("호환성 힌트 (string→string, auth→auth): " + hint2)

  // 어댑터 표시 테스트
  let w_adapted = markWireAdapted(w, "adapter-001")
  print("어댑터 적용 후: " + describeWire(w_adapted))

  return 0
}
